type DebugPanelsProps = {
  eventLog: string;
  blocksJson: string;
};

export function DebugPanels({ eventLog, blocksJson }: DebugPanelsProps) {
  return (
    <section className="xblox-debug-grid">
      <div className="xblox-debug-panel">
        <h2>Host Run Log</h2>
        <pre>{eventLog}</pre>
      </div>
      <div className="xblox-debug-panel">
        <h2>Blocks File Preview</h2>
        <pre>{blocksJson}</pre>
      </div>
    </section>
  );
}
