export function XbloxDndProvider({ children }: { children: ReactNode }) {
  return <DndProvider backend={HTML5Backend}>{children}</DndProvider>;
}

export function createDefaultBlock(kind: BlockPaletteKind): XbloxBlock {
  if (kind === "fetch" || kind === "network" || kind === "httpRequest") {
    return { kind, url: "https://", timeoutMs: 30000, followRedirects: true, storeAs: "response" };
  }
  if (kind === "Parse" || kind === "parse") return { kind, parser: "jq", filter: ".", storeAs: "parsed" };
  if (kind === "shell" || kind === "Shell") return { kind, mode: "shell", shell: "auto", command: "echo hello", timeoutMs: 30000, storeAs: "stdout" };
  if (kind === "runScript") return { kind, method: "return undefined;" };
  if (kind === "command") return { kind, command: { id: "custom.command", label: "Command", type: "button" } };
  if (kind === "setVariable") return { kind, name: "value", expression: "1" };
  if (kind === "getVariable") return { kind, name: "value", target: "lastValue" };
  if (kind === "log") return { kind, level: "trace", message: "value" };
  if (kind === "wait") return { kind, ms: 500 };
  if (kind === "if") return { kind, condition: "true", consequent: [], alternate: [] };
  if (kind === "for") return { kind, initial: "0", final: "3", comparator: "<", modifier: "+1", items: [] };
  if (kind === "while") return { kind, condition: "false", loopLimit: 10, items: [] };
  if (kind === "switch") return { kind, variable: "mode", items: [] };
  if (kind === "case") return { kind, comparator: "===", expression: "\"value\"", consequent: [] };
  if (kind === "switchDefault") return { kind, consequent: [] };
  return { kind: "break" };
}

function isSwitchItem(block: XbloxBlock): block is SwitchItemNode {
  return block.kind === "case" || block.kind === "switchDefault";
}

function blockLabel(block: XbloxBlock): string {
  if (block.kind === "runScript") return block.id ? `runScript ${block.id}` : "runScript";
  if (block.kind === "command") return block.command.label || block.command.id || "command";
  if (block.kind === "setVariable") return `set ${block.name}`;
  if (block.kind === "getVariable") return block.target ? `get ${block.name} -> ${block.target}` : `get ${block.name}`;
  if (block.kind === "log") return `log ${block.level || "trace"} ${block.message}`;
  if (block.kind === "wait") return `wait ${block.ms}ms`;
  if (block.kind === "fetch" || block.kind === "network" || block.kind === "httpRequest") return `${block.kind} ${block.url}`;
  if (block.kind === "Parse" || block.kind === "parse") return `parse ${block.filter || block.query || "."}`;
  if (block.kind === "shell" || block.kind === "Shell") return `shell ${block.command || block.line || block.exe || ""}`;
  if (block.kind === "if") return `if ${block.condition}`;
  if (block.kind === "for") return `for ${block.initial}${block.comparator}${block.final}`;
  if (block.kind === "while") return `while ${block.condition}`;
  if (block.kind === "switch") return `switch ${block.variable}`;
  if (block.kind === "case") return `case ${block.comparator} ${block.expression}`;
  return block.kind;
}

function getChildren(block: XbloxBlock): { key: string; blocks: XbloxBlock[] }[] {
  if (block.kind === "if") {
    return [
      { key: "consequent", blocks: block.consequent },
      { key: "alternate", blocks: block.alternate ?? [] },
    ];
  }
  if (block.kind === "for" || block.kind === "while" || block.kind === "switch") return [{ key: "items", blocks: block.items }];
  if (block.kind === "case" || block.kind === "switchDefault") return [{ key: "consequent", blocks: block.consequent }];
  return [];
}

function commandPayloadFromBlock(block: XbloxBlock | null): CustomCommandItem | null {
  if (!block) return null;
  if (block.kind === "command") return block.command;
  if (block.kind === "runScript") return parseRunCustomCommandPayload(block.method);
  return null;
}

function primaryChildKey(block: XbloxBlock): "consequent" | "items" | null {
  if (block.kind === "if" || block.kind === "case" || block.kind === "switchDefault") return "consequent";
  if (block.kind === "for" || block.kind === "while" || block.kind === "switch") return "items";
  return null;
}

function canContain(parent: XbloxBlock, child: XbloxBlock): boolean {
  if (parent.kind === "switch") return isSwitchItem(child);
  if (isSwitchItem(child)) return false;
  return primaryChildKey(parent) !== null;
}

function itemPath(listPath: string, index: number) {
  return listPath ? `${listPath}/${index}` : String(index);
}

function parseItemPath(path: string) {
  const parts = path.split("/");
  return {
    index: Number(parts[parts.length - 1]),
    listPath: parts.slice(0, -1).join("/"),
  };
}

function parentPathForList(listPath: string) {
  if (!listPath) return null;
  const parts = listPath.split("/");
  return parts.slice(0, -1).join("/");
}

function childKeyForList(listPath: string) {
  if (!listPath) return "";
  const parts = listPath.split("/");
  return parts[parts.length - 1];
}

function hasSelectedAncestor(path: string, selected: Set<string>) {
  let current = parseItemPath(path).listPath;
  while (current) {
    const parent = parentPathForList(current);
    if (parent && selected.has(parent)) return true;
    current = parent ? parseItemPath(parent).listPath : "";
  }
  return false;
}

function cloneBlock<T extends XbloxBlock>(block: T): T {
  return JSON.parse(JSON.stringify(block)) as T;
}

function selectedClipboardBlocks(blocks: BlockNode[], rows: TreeRow[], selected: Set<string>, selection: string | null): XbloxBlock[] {
  const selectedRows = rows.filter((row) => selected.has(row.path) && !hasSelectedAncestor(row.path, selected));
  if (selectedRows.length) return selectedRows.map((row) => cloneBlock(row.block));
  const selectedBlock = selection ? getBlockAtPath(blocks, selection) : null;
  return selectedBlock ? [cloneBlock(selectedBlock)] : [];
}

function serializeClipboard(blocks: XbloxBlock[]) {
  return JSON.stringify({ type: CLIPBOARD_MIME, blocks });
}

function parseClipboardText(text: string): BlockClipboard | null {
  try {
    const parsed = JSON.parse(text);
    if (parsed?.type !== CLIPBOARD_MIME || !Array.isArray(parsed.blocks)) return null;
    return { blocks: parsed.blocks as XbloxBlock[] };
  } catch {
    return null;
  }
}

function flatten(blocks: BlockNode[], open: Set<string>, depth = 0, listPath = ""): TreeRow[] {
  const rows: TreeRow[] = [];
  blocks.forEach((block, index) => {
    const path = itemPath(listPath, index);
    rows.push({ block, path, depth, listPath, index });
    if (!open.has(path)) return;
    for (const group of getChildren(block)) {
      rows.push(...flattenGroup(group.blocks, open, depth + 1, `${path}/${group.key}`));
    }
  });
  return rows;
}

function flattenGroup(blocks: XbloxBlock[], open: Set<string>, depth: number, listPath: string): TreeRow[] {
  const rows: TreeRow[] = [];
  blocks.forEach((block, index) => {
    const path = itemPath(listPath, index);
    rows.push({ block, path, depth, listPath, index });
    if (!open.has(path)) return;
    for (const group of getChildren(block)) {
      rows.push(...flattenGroup(group.blocks, open, depth + 1, `${path}/${group.key}`));
    }
  });
  return rows;
}

export function getBlockAtPath(blocks: BlockNode[], path: string): XbloxBlock | null {
  const parts = path.split("/");
  let list: XbloxBlock[] = blocks;
  let block: XbloxBlock | undefined;
  for (let i = 0; i < parts.length; i += 1) {
    const part = parts[i];
    const index = Number(part);
    if (!Number.isNaN(index)) {
      block = list[index];
      if (!block) return null;
      continue;
    }
    if (!block) return null;
    const group = getChildren(block).find((childGroup) => childGroup.key === part);
    if (!group) return null;
    list = group.blocks;
  }
  return block ?? null;
}

function updateAtPath(blocks: BlockNode[], path: string, patch: Partial<Record<string, unknown>>): BlockNode[] {
  const parts = path.split("/");
  const updateList = (list: XbloxBlock[], partIndex: number): XbloxBlock[] => {
    const index = Number(parts[partIndex]);
    return list.map((block, currentIndex) => {
      if (currentIndex !== index) return block;
      if (partIndex === parts.length - 1) return { ...block, ...patch } as XbloxBlock;
      const key = parts[partIndex + 1];
      if ((key === "consequent" || key === "alternate") && "consequent" in block) {
        return { ...block, [key]: updateList(((block as Extract<BlockNode, { kind: "if" }>)[key] ?? []) as BlockNode[], partIndex + 2) };
      }
      if (key === "items" && "items" in block) {
        return { ...block, items: updateList(block.items, partIndex + 2) as never };
      }
      return block;
    });
  };
  return updateList(blocks, 0) as BlockNode[];
}

function getListAtPath(blocks: BlockNode[], listPath: string): XbloxBlock[] {
  if (!listPath) return blocks;
  const parentPath = parentPathForList(listPath);
  const key = childKeyForList(listPath);
  const parent = parentPath ? getBlockAtPath(blocks, parentPath) : null;
  return parent ? (getChildren(parent).find((group) => group.key === key)?.blocks ?? []) : [];
}

function setListAtPath(blocks: BlockNode[], listPath: string, nextList: XbloxBlock[]): BlockNode[] {
  if (!listPath) return nextList.filter((block): block is BlockNode => !isSwitchItem(block));
  const parentPath = parentPathForList(listPath);
  const key = childKeyForList(listPath);
  if (!parentPath) return blocks;
  return updateAtPath(blocks, parentPath, { [key]: nextList });
}

function canInsertIntoList(blocks: BlockNode[], listPath: string, block: XbloxBlock) {
  if (!listPath) return !isSwitchItem(block);
  const parentPath = parentPathForList(listPath);
  const key = childKeyForList(listPath);
  const parent = parentPath ? getBlockAtPath(blocks, parentPath) : null;
  if (!parent || !getChildren(parent).some((group) => group.key === key)) return false;
  if (parent.kind === "switch") return isSwitchItem(block);
  return canContain(parent, block);
}

function insertIntoList(blocks: BlockNode[], listPath: string, index: number, block: XbloxBlock): BlockNode[] {
  if (!canInsertIntoList(blocks, listPath, block)) return blocks;
  const list = getListAtPath(blocks, listPath);
  const next = [...list];
  next.splice(Math.max(0, Math.min(index, next.length)), 0, block);
  return setListAtPath(blocks, listPath, next);
}

function removeAtPath(blocks: BlockNode[], path: string): { nextBlocks: BlockNode[]; removed: XbloxBlock | null; listPath: string; index: number } {
  const { listPath, index } = parseItemPath(path);
  const list = getListAtPath(blocks, listPath);
  const removed = list[index] ?? null;
  if (!removed) return { nextBlocks: blocks, removed: null, listPath, index };
  return {
    nextBlocks: setListAtPath(blocks, listPath, list.filter((_, currentIndex) => currentIndex !== index)),
    removed,
    listPath,
    index,
  };
}

function deleteSelectedFromList(list: XbloxBlock[], listPath: string, selected: Set<string>): XbloxBlock[] {
  const next: XbloxBlock[] = [];
  list.forEach((block, index) => {
    const path = itemPath(listPath, index);
    if (selected.has(path)) return;
    if (block.kind === "if") {
      next.push({
        ...block,
        consequent: deleteSelectedFromList(block.consequent, `${path}/consequent`, selected) as BlockNode[],
        alternate: deleteSelectedFromList(block.alternate ?? [], `${path}/alternate`, selected) as BlockNode[],
      });
      return;
    }
    if (block.kind === "for" || block.kind === "while") {
      next.push({ ...block, items: deleteSelectedFromList(block.items, `${path}/items`, selected) as BlockNode[] });
      return;
    }
    if (block.kind === "switch") {
      next.push({ ...block, items: deleteSelectedFromList(block.items, `${path}/items`, selected) as SwitchItemNode[] });
      return;
    }
    if (block.kind === "case" || block.kind === "switchDefault") {
      next.push({ ...block, consequent: deleteSelectedFromList(block.consequent, `${path}/consequent`, selected) as BlockNode[] });
      return;
    }
    next.push(block);
  });
  return next;
}

function moveSelectedWithinList(blocks: BlockNode[], listPath: string, selected: Set<string>, direction: -1 | 1) {
  const list = getListAtPath(blocks, listPath);
  const selectedIndices = new Set<number>();
  list.forEach((_, index) => {
    if (selected.has(itemPath(listPath, index))) selectedIndices.add(index);
  });
  if (!selectedIndices.size) return { nextBlocks: blocks, nextSelected: selected };

  const entries = list.map((block, oldIndex) => ({ block, oldIndex, selected: selectedIndices.has(oldIndex) }));
  if (direction < 0) {
    for (let i = 1; i < entries.length; i += 1) {
      if (entries[i].selected && !entries[i - 1].selected) {
        [entries[i - 1], entries[i]] = [entries[i], entries[i - 1]];
      }
    }
  } else {
    for (let i = entries.length - 2; i >= 0; i -= 1) {
      if (entries[i].selected && !entries[i + 1].selected) {
        [entries[i], entries[i + 1]] = [entries[i + 1], entries[i]];
      }
    }
  }

  const nextSelected = new Set<string>();
  entries.forEach((entry, newIndex) => {
    if (entry.selected) nextSelected.add(itemPath(listPath, newIndex));
  });
  return {
    nextBlocks: setListAtPath(
      blocks,
      listPath,
      entries.map((entry) => entry.block),
    ),
    nextSelected,
  };
}

function insertManyIntoList(blocks: BlockNode[], listPath: string, index: number, moving: XbloxBlock[]) {
  if (moving.some((block) => !canInsertIntoList(blocks, listPath, block))) return blocks;
  const list = getListAtPath(blocks, listPath);
  const next = [...list];
  next.splice(Math.max(0, Math.min(index, next.length)), 0, ...moving);
  return setListAtPath(blocks, listPath, next);
}

function moveSelectedAcrossLists(blocks: BlockNode[], activePath: string, selected: Set<string>, direction: -1 | 1) {
  const { listPath } = parseItemPath(activePath);
  const list = getListAtPath(blocks, listPath);
  const selectedIndices = list
    .map((_, index) => index)
    .filter((index) => selected.has(itemPath(listPath, index)));

  if (!selectedIndices.length) return { nextBlocks: blocks, nextSelected: selected };

  const minIndex = Math.min(...selectedIndices);
  const maxIndex = Math.max(...selectedIndices);
  const canMoveWithinList = direction < 0 ? minIndex > 0 : maxIndex < list.length - 1;
  if (canMoveWithinList) return moveSelectedWithinList(blocks, listPath, selected, direction);
  if (!listPath) return { nextBlocks: blocks, nextSelected: selected };

  const parentPath = parentPathForList(listPath);
  if (!parentPath) return { nextBlocks: blocks, nextSelected: selected };

  const parentPosition = parseItemPath(parentPath);
  const moving = selectedIndices.map((index) => list[index]).filter((block): block is XbloxBlock => Boolean(block));
  if (moving.some((block) => !canInsertIntoList(blocks, parentPosition.listPath, block))) {
    return { nextBlocks: blocks, nextSelected: selected };
  }

  const nextChildList = list.filter((_, index) => !selectedIndices.includes(index));
  const withoutMoving = setListAtPath(blocks, listPath, nextChildList);
  const insertIndex = direction < 0 ? parentPosition.index : parentPosition.index + 1;
  if (moving.some((block) => !canInsertIntoList(withoutMoving, parentPosition.listPath, block))) {
    return { nextBlocks: blocks, nextSelected: selected };
  }
  const nextBlocks = insertManyIntoList(withoutMoving, parentPosition.listPath, insertIndex, moving);
  const nextSelected = new Set(moving.map((_, offset) => itemPath(parentPosition.listPath, insertIndex + offset)));

  return { nextBlocks, nextSelected };
}

function PaletteButton({ kind }: { kind: BlockPaletteKind }) {
  const [, dragRef] = useDrag(
    () => ({
      type: DND_TYPE,
      item: { source: "palette", kind } satisfies DragItem,
    }),
    [kind],
  );
  const ref = useCallback(
    (el: HTMLButtonElement | null) => {
      dragRef(el);
    },
    [dragRef],
  );
  return (
    <button ref={ref} type="button" style={styles.button} className="xblox-palette-item">
      {kind}
    </button>
  );
}

function CommandPaletteButton({ command }: { command: CommandPaletteBlock }) {
  const [, dragRef] = useDrag(
    () => ({
      type: DND_TYPE,
      item: { source: "command", block: command.block } satisfies DragItem,
    }),
    [command],
  );
  const ref = useCallback(
    (el: HTMLButtonElement | null) => {
      dragRef(el);
    },
    [dragRef],
  );
  return (
    <button ref={ref} type="button" style={styles.button} className="xblox-palette-item xblox-command-palette-item" title={command.description}>
      <strong>{command.label}</strong>
      <span>{command.id}</span>
      {command.description ? <small>{command.description}</small> : null}
    </button>
  );
}

function NativePaletteButton({ item }: { item: NativePaletteBlock }) {
  const [, dragRef] = useDrag(
    () => ({
      type: DND_TYPE,
      item: { source: "command", block: item.block } satisfies DragItem,
    }),
    [item],
  );
  const ref = useCallback(
    (el: HTMLButtonElement | null) => {
      dragRef(el);
    },
    [dragRef],
  );
  return (
    <button ref={ref} type="button" style={styles.button} className="xblox-palette-item xblox-native-palette-item" title={item.description}>
      <strong>{item.label || item.kind}</strong>
      <span>{item.kind}</span>
      {item.description ? <small>{item.description}</small> : null}
    </button>
  );
}

function TreeItem({
  row,
  selected,
  expanded,
  status,
  onSelect,
  onActivate,
  onToggle,
  onDropLine,
  onPatch,
  onOpen,
  onContextMenu,
}: {
  row: TreeRow;
  selected: boolean;
  expanded: boolean;
  status?: BlockRunState;
  onSelect: (event: MouseEvent<HTMLDivElement>) => void;
  onActivate: () => void;
  onToggle: () => void;
  onDropLine: (targetPath: string, placement: DropPlacement, item: DragItem) => void;
  onPatch: (patch: Partial<Record<string, unknown>>) => void;
  onOpen: () => void;
  onContextMenu: (event: MouseEvent<HTMLDivElement>) => void;
}) {
  const hasChildren = getChildren(row.block).some((group) => group.blocks.length > 0);
  const [dropPlacement, setDropPlacement] = useState<DropPlacement | null>(null);
  const rowRef = useRef<HTMLDivElement | null>(null);
  const [, dragRef] = useDrag(
    () => ({
      type: DND_TYPE,
      item: { source: "tree", path: row.path } satisfies DragItem,
    }),
    [row.path],
  );
  const [{ isOver }, dropRef] = useDrop(
    () => ({
      accept: DND_TYPE,
      hover: (_item: DragItem, monitor) => {
        const clientOffset = monitor.getClientOffset();
        const node = rowRef.current;
        if (!clientOffset || !node) return;
        const rect = node.getBoundingClientRect();
        setDropPlacement(clientOffset.y < rect.top + rect.height / 2 ? "before" : "after");
      },
      drop: (item: DragItem) => {
        onDropLine(row.path, dropPlacement ?? "after", item);
        setDropPlacement(null);
      },
      collect: (monitor) => ({ isOver: monitor.isOver({ shallow: true }) }),
    }),
    [dropPlacement, onDropLine, row.path],
  );
  const ref = useCallback(
    (el: HTMLDivElement | null) => {
      rowRef.current = el;
      dragRef(dropRef(el));
    },
    [dragRef, dropRef],
  );
  const border =
    status?.status === "ok"
      ? "#22c55e"
      : status?.status === "error" || status?.status === "skipped"
        ? "#ef4444"
        : status?.status === "running"
          ? "#38bdf8"
          : selected
            ? "#38bdf8"
            : "transparent";
  const background =
    status?.status === "error" || status?.status === "skipped"
      ? "var(--xblox-error-row-bg, #2f0f16)"
      : isOver
        ? "var(--xblox-drop-row-bg, #082f49)"
        : selected
          ? "var(--xblox-selected-row-bg, #1e293b)"
          : "var(--xblox-row-bg, #020617)";
  return (
    <div
      ref={ref}
      role="treeitem"
      aria-selected={selected}
      aria-expanded={hasChildren ? expanded : undefined}
      onClick={onSelect}
      onContextMenu={onContextMenu}
      onDoubleClick={onOpen}
      title={status?.error}
      className="xblox-tree-row"
      data-drop-placement={isOver ? (dropPlacement ?? "after") : undefined}
      style={{
        display: "flex",
        alignItems: "center",
        gap: 8,
        marginBottom: 4,
        padding: "6px 8px",
        paddingLeft: 8 + row.depth * 18,
        border: `1px solid ${border}`,
        borderRadius: 8,
        background,
        boxShadow: selected ? "inset 3px 0 0 #38bdf8" : undefined,
      }}
    >
      <button
        type="button"
        onClick={(event) => {
          event.stopPropagation();
          onToggle();
        }}
      >
        {hasChildren ? (expanded ? "v" : ">") : ""}
      </button>
      <strong>{row.block.kind}</strong>
      <InlineBlockEditor block={row.block} path={row.path} onActivate={onActivate} onPatch={onPatch} onEnter={onOpen} />
      {status?.status && status.status !== "idle" ? (
        <small className={`xblox-status-pill xblox-status-pill--${status.status}`} style={{ marginLeft: "auto" }}>
          {status.status}
        </small>
      ) : null}
    </div>
  );
}

function InlineBlockEditor({
  block,
  path,
  onActivate,
  onPatch,
  onEnter,
}: {
  block: XbloxBlock;
  path: string;
  onActivate: () => void;
  onPatch: (patch: Partial<Record<string, unknown>>) => void;
  onEnter: () => void;
}) {
  const stopTreeMouse = (event: MouseEvent<HTMLInputElement | HTMLSelectElement>) => {
    event.stopPropagation();
  };
  const handleFocus = () => {
    onActivate();
  };
  const stopTreeKeys = (event: KeyboardEvent<HTMLInputElement | HTMLSelectElement>) => {
    event.stopPropagation();
    if (event.key === "Enter") {
      event.preventDefault();
      event.currentTarget.blur();
      onEnter();
    }
  };
  const inputClass = "xblox-inline-input";

  if (block.kind === "if" || block.kind === "while") {
    return (
      <label className="xblox-inline-expr">
        <span>{block.kind === "if" ? "condition" : "while"}</span>
        <input
          data-xblox-inline-path={path}
          className={inputClass}
          value={block.condition}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ condition: event.target.value })}
        />
      </label>
    );
  }

  if (block.kind === "switch") {
    return (
      <label className="xblox-inline-expr">
        <span>switch</span>
        <input
          data-xblox-inline-path={path}
          className={inputClass}
          value={block.variable}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ variable: event.target.value })}
        />
      </label>
    );
  }

  if (block.kind === "setVariable") {
    return (
      <span className="xblox-inline-expr">
        <span>set</span>
        <input
          data-xblox-inline-path={path}
          className="xblox-inline-input small"
          value={block.name}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ name: event.target.value })}
          title="Variable name"
        />
        <input
          data-xblox-inline-path={path}
          className={inputClass}
          value={block.expression ?? (typeof block.value === "string" || typeof block.value === "number" || typeof block.value === "boolean" ? String(block.value) : "")}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ expression: event.target.value })}
          title="Expression"
        />
      </span>
    );
  }

  if (block.kind === "getVariable") {
    return (
      <span className="xblox-inline-expr">
        <span>get</span>
        <input
          data-xblox-inline-path={path}
          className="xblox-inline-input small"
          value={block.name}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ name: event.target.value })}
          title="Variable name"
        />
        <input
          data-xblox-inline-path={path}
          className={inputClass}
          value={block.target ?? ""}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ target: event.target.value })}
          title="Optional target variable"
        />
      </span>
    );
  }

  if (block.kind === "log") {
    return (
      <span className="xblox-inline-expr">
        <span>log</span>
        <select
          data-xblox-inline-path={path}
          className="xblox-inline-select"
          value={block.level || "trace"}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ level: event.target.value })}
        >
          <option value="trace">trace</option>
          <option value="debug">debug</option>
          <option value="info">info</option>
          <option value="warn">warn</option>
          <option value="error">error</option>
          <option value="critical">critical</option>
        </select>
        <input
          data-xblox-inline-path={path}
          className={inputClass}
          value={block.message}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ message: event.target.value })}
          title="Message or expression"
        />
      </span>
    );
  }

  if (block.kind === "case") {
    return (
      <span className="xblox-inline-expr">
        <span>case</span>
        <select
          data-xblox-inline-path={path}
          className="xblox-inline-select"
          value={block.comparator}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ comparator: event.target.value })}
        >
          <option value="===">===</option>
          <option value="!==">!==</option>
          <option value=">">&gt;</option>
          <option value=">=">&gt;=</option>
          <option value="<">&lt;</option>
          <option value="<=">&lt;=</option>
        </select>
        <input
          data-xblox-inline-path={path}
          className={inputClass}
          value={block.expression}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ expression: event.target.value })}
        />
      </span>
    );
  }

  if (block.kind === "for") {
    return (
      <span className="xblox-inline-expr">
        <span>for</span>
        <input
          data-xblox-inline-path={path}
          className="xblox-inline-input small"
          value={block.initial}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ initial: event.target.value })}
          title="Initial"
        />
        <input
          data-xblox-inline-path={path}
          className="xblox-inline-input tiny"
          value={block.comparator}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ comparator: event.target.value })}
          title="Comparator"
        />
        <input
          data-xblox-inline-path={path}
          className="xblox-inline-input small"
          value={block.final}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ final: event.target.value })}
          title="Final"
        />
        <input
          data-xblox-inline-path={path}
          className="xblox-inline-input tiny"
          value={block.modifier}
          onMouseDown={stopTreeMouse}
          onClick={stopTreeMouse}
          onFocus={handleFocus}
          onKeyDown={stopTreeKeys}
          onChange={(event) => onPatch({ modifier: event.target.value })}
          title="Modifier"
        />
      </span>
    );
  }

  return <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{blockLabel(block)}</span>;
}

function RootDropZone({ onDropBlock }: { onDropBlock: (item: DragItem) => void }) {
  const [{ isOver }, dropRef] = useDrop(
    () => ({
      accept: DND_TYPE,
      drop: onDropBlock,
      collect: (monitor) => ({ isOver: monitor.isOver({ shallow: true }) }),
    }),
    [onDropBlock],
  );
  const ref = useCallback(
    (el: HTMLDivElement | null) => {
      dropRef(el);
    },
    [dropRef],
  );
  return (
    <div ref={ref} className={`xblox-root-drop ${isOver ? "is-over" : ""}`}>
      Drop here to append as a root block
    </div>
  );
}

export function XbloxBuilder({
  value,
  onChange,
  rootScope = {},
  onRootScopeChange,
  runState,
  onRunBlock,
  onRunChain,
  onStopRun,
  running = false,
  selectedPath,
  onSelectionChange,
  onSave,
  saveDisabled = false,
  theme = "dark",
  onToggleTheme,
  palette = defaultPalette,
  nativePalette = [],
  commandPalette = [],
  className,
}: XbloxBuilderProps) {
  const [internalSelectedPath, setInternalSelectedPath] = useState<string | null>(value.length ? "0" : null);
  const [selectedPaths, setSelectedPaths] = useState<Set<string>>(() => new Set(value.length ? ["0"] : []));
  const [anchorPath, setAnchorPath] = useState<string | null>(value.length ? "0" : null);
  const [open, setOpen] = useState<Set<string>>(() => new Set(["1", "1/consequent/1", "1/alternate/1", "2", "2/items/0", "2/items/1", "4"]));
  const [folderStack, setFolderStack] = useState<FolderFrame[]>([]);
  const [openPaletteGroups, setOpenPaletteGroups] = useState<Set<string>>(readOpenPaletteGroups);
  const [paletteQuery, setPaletteQuery] = useState("");
  const [propsDialogOpen, setPropsDialogOpen] = useState(false);
  const rootScopeJson = useMemo(() => JSON.stringify(rootScope, null, 2), [rootScope]);
  const [rootScopeDraft, setRootScopeDraft] = useState(rootScopeJson);
  const [rootScopeError, setRootScopeError] = useState<string | null>(null);
  const [clipboard, setClipboard] = useState<BlockClipboard | null>(null);
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const clipboardRef = useRef<BlockClipboard | null>(null);
  const treeRef = useRef<HTMLDivElement>(null);
  const locallyPublishedSelectionRef = useRef<string | null>(null);
  const refocusTree = useCallback(() => {
    window.requestAnimationFrame(() => {
      treeRef.current?.focus({ preventScroll: true });
    });
  }, []);
  const selection = selectedPath ?? internalSelectedPath;
  const normalizedPaletteQuery = paletteQuery.trim().toLowerCase();
  const groupedPalette = useMemo(() => {
    const enabled = new Set(palette);
    const used = new Set<BlockPaletteKind>();
    const groups = paletteGroups
      .map((group) => {
        const kinds = group.kinds.filter((kind) => enabled.has(kind) && (!normalizedPaletteQuery || kind.toLowerCase().includes(normalizedPaletteQuery)));
        kinds.forEach((kind) => used.add(kind));
        return { ...group, kinds };
      })
      .filter((group) => group.kinds.length);
    const other = palette.filter((kind) => !used.has(kind) && (!normalizedPaletteQuery || kind.toLowerCase().includes(normalizedPaletteQuery)));
    return other.length ? [...groups, { id: "other", label: "Other", kinds: other, defaultOpen: true }] : groups;
  }, [normalizedPaletteQuery, palette]);
  const filteredCommandPalette = useMemo(() => {
    if (!normalizedPaletteQuery) return commandPalette;
    return commandPalette.filter((command) => {
      const haystack = `${command.label} ${command.id} ${command.description ?? ""}`.toLowerCase();
      return haystack.includes(normalizedPaletteQuery);
    });
  }, [commandPalette, normalizedPaletteQuery]);
  const groupedNativePalette = useMemo(() => {
    const groups = new Map<string, NativePaletteBlock[]>();
    for (const item of nativePalette) {
      const haystack = `${item.kind} ${item.label ?? ""} ${item.group ?? ""}`.toLowerCase();
      if (normalizedPaletteQuery && !haystack.includes(normalizedPaletteQuery)) continue;
      const group = item.group || "Native";
      groups.set(group, [...(groups.get(group) ?? []), item]);
    }
    return [...groups.entries()].map(([label, items]) => ({ label, items }));
  }, [nativePalette, normalizedPaletteQuery]);
  const currentRootListPath = folderStack[folderStack.length - 1]?.listPath ?? "";
  const rows = useMemo(
    () =>
      currentRootListPath
        ? flattenGroup(getListAtPath(value, currentRootListPath), open, 0, currentRootListPath)
        : flatten(value, open),
    [currentRootListPath, open, value],
  );
  const currentLevelBlocks = useMemo(() => {
    const list = currentRootListPath ? getListAtPath(value, currentRootListPath) : value;
    return list.filter((block): block is BlockNode => !isSwitchItem(block));
  }, [currentRootListPath, value]);
  const selectedBlock = selection ? getBlockAtPath(value, selection) : null;
  const selectedCommandPayload = commandPayloadFromBlock(selectedBlock);
  const executeAction = useCallback(async (actionId: string, context?: unknown) => {
    const action = actionStore.getAction(actionId);
    if (!action || action.disabled) return;
    await action.handler(context);
  }, []);

  useEffect(() => {
    if (!selectedPath) return;
    setInternalSelectedPath(selectedPath);
    if (locallyPublishedSelectionRef.current === selectedPath) {
      locallyPublishedSelectionRef.current = null;
      return;
    }
    setSelectedPaths((current) => (current.has(selectedPath) ? current : new Set([selectedPath])));
    setAnchorPath(selectedPath);
  }, [selectedPath]);

  useEffect(() => {
    persistOpenPaletteGroups(openPaletteGroups);
  }, [openPaletteGroups]);

  useEffect(() => {
    if (!selectedBlock) setPropsDialogOpen(false);
  }, [selectedBlock]);

  useEffect(() => {
    setRootScopeDraft(rootScopeJson);
    setRootScopeError(null);
  }, [rootScopeJson]);

  useEffect(() => {
    clipboardRef.current = clipboard;
  }, [clipboard]);

  useEffect(() => {
    if (!contextMenu) return;
    const close = () => setContextMenu(null);
    const closeOnEscape = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") close();
    };
    window.addEventListener("click", close);
    window.addEventListener("keydown", closeOnEscape);
    window.addEventListener("resize", close);
    return () => {
      window.removeEventListener("click", close);
      window.removeEventListener("keydown", closeOnEscape);
      window.removeEventListener("resize", close);
    };
  }, [contextMenu]);

  const publishSelection = useCallback(
    (path: string | null) => {
      const block = path ? getBlockAtPath(value, path) : null;
      locallyPublishedSelectionRef.current = path;
      setInternalSelectedPath(path);
      onSelectionChange?.(path, block);
    },
    [onSelectionChange, value],
  );

  const selectRow = useCallback(
    (path: string, event?: MouseEvent<HTMLDivElement>) => {
      if (event?.shiftKey && anchorPath) {
        const from = rows.findIndex((row) => row.path === anchorPath);
        const to = rows.findIndex((row) => row.path === path);
        if (from >= 0 && to >= 0) {
          const [start, end] = from < to ? [from, to] : [to, from];
          const next = new Set(rows.slice(start, end + 1).map((row) => row.path));
          setSelectedPaths(next);
          publishSelection(path);
          return;
        }
      }

      if (event?.ctrlKey || event?.metaKey) {
        setSelectedPaths((current) => {
          const next = new Set(current);
          if (next.has(path)) next.delete(path);
          else next.add(path);
          return next.size ? next : new Set([path]);
        });
        setAnchorPath(path);
        publishSelection(path);
        return;
      }

      setSelectedPaths(new Set([path]));
      setAnchorPath(path);
      publishSelection(path);
    },
    [anchorPath, publishSelection, rows],
  );

  const moveSelection = useCallback(
    (delta: number) => {
      if (!rows.length) return;
      const index = Math.max(0, rows.findIndex((row) => row.path === selection));
      selectRow(rows[(index + delta + rows.length) % rows.length].path);
    },
    [rows, selectRow, selection],
  );

  const extendKeyboardSelection = useCallback(
    (delta: number) => {
      if (!rows.length) return;
      const focusIndex = Math.max(0, rows.findIndex((row) => row.path === selection));
      const anchorIndex = anchorPath ? rows.findIndex((row) => row.path === anchorPath) : focusIndex;
      const nextFocusIndex = Math.max(0, Math.min(rows.length - 1, focusIndex + delta));
      const resolvedAnchorIndex = anchorIndex >= 0 ? anchorIndex : focusIndex;
      const [start, end] =
        resolvedAnchorIndex < nextFocusIndex ? [resolvedAnchorIndex, nextFocusIndex] : [nextFocusIndex, resolvedAnchorIndex];
      const nextPath = rows[nextFocusIndex].path;
      setSelectedPaths(new Set(rows.slice(start, end + 1).map((row) => row.path)));
      if (!anchorPath) setAnchorPath(rows[resolvedAnchorIndex].path);
      publishSelection(nextPath);
    },
    [anchorPath, publishSelection, rows, selection],
  );

  const runSelected = useCallback(() => {
    if (!onRunBlock) return;
    const targets = rows
      .filter((row) => selectedPaths.has(row.path) && !hasSelectedAncestor(row.path, selectedPaths))
      .map((row) => ({ path: row.path, block: row.block }));
    if (!targets.length && selection && selectedBlock) targets.push({ path: selection, block: selectedBlock });
    void (async () => {
      for (const target of targets) {
        await onRunBlock(target.block, target.path);
      }
    })();
  }, [onRunBlock, rows, selectedBlock, selectedPaths, selection]);

  const runCurrentChain = useCallback(() => {
    if (!onRunChain || !currentLevelBlocks.length) return;
    void onRunChain(currentLevelBlocks, currentRootListPath);
  }, [currentLevelBlocks, currentRootListPath, onRunChain]);

  const enterSelectedBlock = useCallback(() => {
    if (!selection || !selectedBlock) return;
    const childGroups = getChildren(selectedBlock);
    if (!childGroups.length) return;

    setOpen((current) => new Set(current).add(selection));
    const firstChildGroup = childGroups.find((group) => group.blocks.length > 0) ?? childGroups[0];
    const nextRootListPath = `${selection}/${firstChildGroup.key}`;
    setFolderStack((current) => [...current, { listPath: nextRootListPath, entryPath: selection }]);

    const childPath = firstChildGroup.blocks.length ? `${nextRootListPath}/0` : null;
    setSelectedPaths(childPath ? new Set([childPath]) : new Set());
    setAnchorPath(childPath);
    publishSelection(childPath);
    refocusTree();
  }, [publishSelection, refocusTree, selectedBlock, selection]);

  const navigateToParentBlock = useCallback(() => {
    if (folderStack.length) {
      const frame = folderStack[folderStack.length - 1];
      setFolderStack((current) => current.slice(0, -1));
      setSelectedPaths(new Set([frame.entryPath]));
      setAnchorPath(frame.entryPath);
      publishSelection(frame.entryPath);
      refocusTree();
      return;
    }

    if (!selection) return;
    const parentPath = parentPathForList(parseItemPath(selection).listPath);
    if (!parentPath) return;
    setSelectedPaths(new Set([parentPath]));
    setAnchorPath(parentPath);
    publishSelection(parentPath);
    refocusTree();
  }, [folderStack, publishSelection, refocusTree, selection]);

  const selectSinglePath = useCallback(
    (path: string) => {
      setSelectedPaths(new Set([path]));
      setAnchorPath(path);
      publishSelection(path);
      refocusTree();
    },
    [publishSelection, refocusTree],
  );

  const moveRightThroughTree = useCallback(() => {
    if (!selection) return;
    const block = getBlockAtPath(value, selection);
    const childGroups = block ? getChildren(block) : [];
    const firstChildGroup = childGroups.find((group) => group.blocks.length > 0);

    if (firstChildGroup) {
      setOpen((current) => new Set(current).add(selection));
      selectSinglePath(`${selection}/${firstChildGroup.key}/0`);
      return;
    }

    const index = rows.findIndex((row) => row.path === selection);
    if (index >= 0 && index < rows.length - 1) selectSinglePath(rows[index + 1].path);
  }, [rows, selectSinglePath, selection, value]);

  const moveLeftThroughTree = useCallback(() => {
    if (!selection) return;
    const block = getBlockAtPath(value, selection);
    const childGroups = block ? getChildren(block) : [];
    const hasVisibleChildren = childGroups.some((group) => group.blocks.length > 0);

    if (hasVisibleChildren && open.has(selection)) {
      setOpen((current) => {
        const next = new Set(current);
        next.delete(selection);
        return next;
      });
      return;
    }

    const index = rows.findIndex((row) => row.path === selection);
    if (index > 0) selectSinglePath(rows[index - 1].path);
  }, [open, rows, selectSinglePath, selection, value]);

  const focusInlineEditor = useCallback(() => {
    if (!selection || !treeRef.current) return;
    const controls = Array.from(treeRef.current.querySelectorAll<HTMLElement>("[data-xblox-inline-path]"));
    const editor = controls.find((control) => control.dataset.xbloxInlinePath === selection);
    editor?.focus();
    if (editor instanceof HTMLInputElement) editor.select();
  }, [selection]);

  const deleteSelected = useCallback(() => {
    if (!selectedPaths.size) return;
    const nextBlocks = deleteSelectedFromList(value, "", selectedPaths).filter((block): block is BlockNode => !isSwitchItem(block));
    onChange(nextBlocks);
    const nextRows = currentRootListPath
      ? flattenGroup(getListAtPath(nextBlocks, currentRootListPath), open, 0, currentRootListPath)
      : flatten(nextBlocks, open);
    const nextPath = nextRows[0]?.path ?? null;
    setSelectedPaths(nextPath ? new Set([nextPath]) : new Set());
    setAnchorPath(nextPath);
    publishSelection(nextPath);
  }, [currentRootListPath, onChange, open, publishSelection, selectedPaths, value]);

  const moveSelectedRows = useCallback(
    (direction: -1 | 1) => {
      const activePath = selection ?? [...selectedPaths][0];
      if (!activePath) return;
      const { nextBlocks, nextSelected } = moveSelectedAcrossLists(value, activePath, selectedPaths, direction);
      onChange(nextBlocks);
      setSelectedPaths(nextSelected);
      const nextPath = [...nextSelected][direction < 0 ? 0 : nextSelected.size - 1] ?? null;
      setAnchorPath(nextPath);
      publishSelection(nextPath);
    },
    [onChange, publishSelection, selectedPaths, selection, value],
  );

  const copySelected = useCallback(
    async (context?: { path?: string }) => {
      const contextPath = context?.path;
      const contextBlock = contextPath && !selectedPaths.has(contextPath) ? getBlockAtPath(value, contextPath) : null;
      const blocks = contextBlock ? [cloneBlock(contextBlock)] : selectedClipboardBlocks(value, rows, selectedPaths, selection);
      if (!blocks.length) return;

      const nextClipboard = { blocks };
      setClipboard(nextClipboard);
      clipboardRef.current = nextClipboard;
      try {
        await navigator.clipboard?.writeText(serializeClipboard(blocks));
      } catch {
        /* Native clipboard writes are best-effort in WebView/dev contexts. */
      }
    },
    [rows, selectedPaths, selection, value],
  );

  const pasteClipboard = useCallback(
    async (context?: { path?: string }) => {
      let source = clipboardRef.current;
      if (!source) {
        try {
          const text = await navigator.clipboard?.readText();
          source = text ? parseClipboardText(text) : null;
        } catch {
          source = null;
        }
      }
      if (!source?.blocks.length) return;

      const targetPath = context?.path ?? selection;
      const targetBlock = targetPath ? getBlockAtPath(value, targetPath) : null;
      let targetListPath = currentRootListPath;
      let targetIndex = getListAtPath(value, targetListPath).length;
      let openPath: string | null = null;

      if (targetPath && targetBlock) {
        const childKey = primaryChildKey(targetBlock);
        const childListPath = childKey ? `${targetPath}/${childKey}` : null;
        if (childListPath && source.blocks.every((block) => canInsertIntoList(value, childListPath, block))) {
          targetListPath = childListPath;
          targetIndex = getListAtPath(value, childListPath).length;
          openPath = targetPath;
        } else {
          const parsed = parseItemPath(targetPath);
          targetListPath = parsed.listPath;
          targetIndex = parsed.index + 1;
        }
      }

      if (!source.blocks.every((block) => canInsertIntoList(value, targetListPath, block))) return;
      const blocksToPaste = source.blocks.map((block) => cloneBlock(block));
      let nextBlocks = value;
      blocksToPaste.forEach((block, offset) => {
        nextBlocks = insertIntoList(nextBlocks, targetListPath, targetIndex + offset, block);
      });

      const nextSelected = new Set(blocksToPaste.map((_, offset) => itemPath(targetListPath, targetIndex + offset)));
      const nextPath = [...nextSelected][0] ?? null;
      onChange(nextBlocks);
      if (openPath) setOpen((current) => new Set(current).add(openPath));
      setSelectedPaths(nextSelected);
      setAnchorPath(nextPath);
      publishSelection(nextPath);
      refocusTree();
    },
    [currentRootListPath, onChange, publishSelection, refocusTree, selection, value],
  );

  const clipboardActions = useMemo(
    () => [
      {
        id: COPY_ACTION_ID,
        label: "Copy",
        icon: Copy,
        shortcut: "ctrl+c",
        disabled: !selectedPaths.size,
      },
      {
        id: PASTE_ACTION_ID,
        label: "Paste",
        icon: ClipboardPaste,
        shortcut: "ctrl+v",
        disabled: false,
      },
    ],
    [selectedPaths.size],
  );

  useEffect(() => {
    actionStore.registerAction({
      id: COPY_ACTION_ID,
      label: "Copy",
      icon: Copy,
      group: "Clipboard",
      shortcut: "ctrl+c",
      visibilities: { Toolbar: true, ContextMenu: true },
      disabled: !selectedPaths.size,
      handler: copySelected,
    });
    actionStore.registerAction({
      id: PASTE_ACTION_ID,
      label: "Paste",
      icon: ClipboardPaste,
      group: "Clipboard",
      shortcut: "ctrl+v",
      visibilities: { Toolbar: true, ContextMenu: true },
      disabled: false,
      handler: pasteClipboard,
    });
    return () => {
      actionStore.unregisterAction(COPY_ACTION_ID);
      actionStore.unregisterAction(PASTE_ACTION_ID);
    };
  }, [copySelected, pasteClipboard, selectedPaths.size]);

  const dropIntoRoot = useCallback(
    (item: DragItem) => {
      if (item.source === "palette" || item.source === "command") {
        const block = item.source === "palette" ? createDefaultBlock(item.kind) : item.block;
        if (!canInsertIntoList(value, currentRootListPath, block)) return;
        const targetIndex = getListAtPath(value, currentRootListPath).length;
        onChange(insertIntoList(value, currentRootListPath, targetIndex, block));
        selectRow(itemPath(currentRootListPath, targetIndex));
        return;
      }
      const removed = removeAtPath(value, item.path);
      if (!removed.removed || !canInsertIntoList(removed.nextBlocks, currentRootListPath, removed.removed)) return;
      const targetIndex = getListAtPath(removed.nextBlocks, currentRootListPath).length;
      const nextBlocks = insertIntoList(removed.nextBlocks, currentRootListPath, targetIndex, removed.removed);
      onChange(nextBlocks);
      selectRow(itemPath(currentRootListPath, targetIndex));
    },
    [currentRootListPath, onChange, selectRow, value],
  );

  const handleDropLine = useCallback(
    (targetPath: string, placement: DropPlacement, item: DragItem) => {
      const targetPosition = parseItemPath(targetPath);
      const targetList = targetPosition.listPath;
      const targetIndex = targetPosition.index + (placement === "after" ? 1 : 0);
      let movingBlock =
        item.source === "palette"
          ? createDefaultBlock(item.kind)
          : item.source === "command"
            ? cloneBlock(item.block)
            : getBlockAtPath(value, item.path);
      if (!movingBlock) return;

      let nextBlocks = value;
      let insertIndex = targetIndex;
      if (item.source === "tree") {
        if (item.path === targetPath) return;
        if (targetList === item.path || targetList.startsWith(`${item.path}/`)) return;
        const removed = removeAtPath(value, item.path);
        if (!removed.removed) return;
        movingBlock = removed.removed;
        nextBlocks = removed.nextBlocks;
        if (removed.listPath === targetList && removed.index < targetIndex) insertIndex -= 1;
        if (removed.listPath === targetList && (insertIndex === removed.index || insertIndex === removed.index + 1)) return;
      }

      if (!canInsertIntoList(nextBlocks, targetList, movingBlock)) return;
      nextBlocks = insertIntoList(nextBlocks, targetList, insertIndex, movingBlock);
      const nextPath = itemPath(targetList, insertIndex);
      onChange(nextBlocks);
      setSelectedPaths(new Set([nextPath]));
      setAnchorPath(nextPath);
      publishSelection(nextPath);
    },
    [onChange, publishSelection, value],
  );

  const updateSelected = useCallback(
    (patch: Partial<Record<string, unknown>>) => {
      if (!selection) return;
      onChange(updateAtPath(value, selection, patch));
    },
    [onChange, selection, value],
  );

  const applyRootScopeDraft = useCallback(() => {
    if (!onRootScopeChange) return;
    try {
      const parsed = rootScopeDraft.trim() ? JSON.parse(rootScopeDraft) : {};
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        setRootScopeError("Root scope must be a JSON object.");
        return;
      }
      setRootScopeError(null);
      onRootScopeChange(parsed as Record<string, unknown>);
    } catch (error) {
      setRootScopeError(error instanceof Error ? error.message : "Invalid JSON.");
    }
  }, [onRootScopeChange, rootScopeDraft]);

  const propertyEditor = selectedBlock ? (
    <div style={{ display: "grid", gap: 10 }}>
      <label>
        Kind
        <input value={selectedBlock.kind} disabled style={styles.input} />
      </label>
      {"id" in selectedBlock ? (
        <label>
          ID
          <input value={selectedBlock.id ?? ""} onChange={(event) => updateSelected({ id: event.target.value })} style={styles.input} />
        </label>
      ) : null}
      {"condition" in selectedBlock ? (
        <label>
          Condition
          <input value={selectedBlock.condition} onChange={(event) => updateSelected({ condition: event.target.value })} style={styles.input} />
        </label>
      ) : null}
      {"method" in selectedBlock ? (
        <label>
          Method
          <textarea value={selectedBlock.method} onChange={(event) => updateSelected({ method: event.target.value })} rows={5} style={styles.input} />
        </label>
      ) : null}
      {selectedBlock.kind === "setVariable" || selectedBlock.kind === "getVariable" ? (
        <label>
          Name
          <input value={selectedBlock.name} onChange={(event) => updateSelected({ name: event.target.value })} style={styles.input} />
        </label>
      ) : null}
      {selectedBlock.kind === "setVariable" ? (
        <>
          <label>
            Expression
            <input value={selectedBlock.expression ?? ""} onChange={(event) => updateSelected({ expression: event.target.value })} style={styles.input} />
          </label>
          <label>
            Literal JSON value
            <textarea
              value={selectedBlock.value == null ? "" : JSON.stringify(selectedBlock.value, null, 2)}
              onChange={(event) => {
                const text = event.target.value.trim();
                if (!text) updateSelected({ value: undefined });
                else {
                  try {
                    updateSelected({ value: JSON.parse(text), expression: undefined });
                  } catch {
                    updateSelected({ value: text, expression: undefined });
                  }
                }
              }}
              rows={3}
              style={styles.input}
            />
          </label>
        </>
      ) : null}
      {selectedBlock.kind === "getVariable" ? (
        <label>
          Target
          <input value={selectedBlock.target ?? ""} onChange={(event) => updateSelected({ target: event.target.value })} style={styles.input} />
        </label>
      ) : null}
      {selectedBlock.kind === "log" ? (
        <>
          <label>
            Level
            <select value={selectedBlock.level || "trace"} onChange={(event) => updateSelected({ level: event.target.value })} style={styles.input}>
              <option value="trace">trace</option>
              <option value="debug">debug</option>
              <option value="info">info</option>
              <option value="warn">warn</option>
              <option value="error">error</option>
              <option value="critical">critical</option>
            </select>
          </label>
          <label>
            Message
            <input value={selectedBlock.message} onChange={(event) => updateSelected({ message: event.target.value })} style={styles.input} />
          </label>
        </>
      ) : null}
      {selectedCommandPayload ? (
        <CommandPropsEditor
          value={selectedCommandPayload}
          inputStyle={styles.input}
          onChange={(command) =>
            selectedBlock.kind === "command"
              ? updateSelected({ id: command.id, command })
              : updateSelected({ method: customCommandToRunScriptMethod(command) })
          }
        />
      ) : null}
      {"ms" in selectedBlock ? (
        <label>
          Milliseconds
          <input type="number" value={selectedBlock.ms} onChange={(event) => updateSelected({ ms: Number(event.target.value) })} style={styles.input} />
        </label>
      ) : null}
      {"variable" in selectedBlock ? (
        <label>
          Variable
          <input value={selectedBlock.variable} onChange={(event) => updateSelected({ variable: event.target.value })} style={styles.input} />
        </label>
      ) : null}
      {"expression" in selectedBlock ? (
        <label>
          Expression
          <input value={selectedBlock.expression} onChange={(event) => updateSelected({ expression: event.target.value })} style={styles.input} />
        </label>
      ) : null}
    </div>
  ) : (
    <p>Select a block to edit properties.</p>
  );

  return (
    <>
    <section className={className ?? "xblox-builder"} style={styles.shell}>
      <aside style={styles.panel} className="xblox-palette">
        <div className="xblox-palette-head">
          <h3>Block Palette</h3>
          {onToggleTheme ? (
            <button
              type="button"
              onClick={onToggleTheme}
              className="xblox-palette-theme-toggle"
              title={theme === "dark" ? "Switch to light theme" : "Switch to dark theme"}
              aria-label={theme === "dark" ? "Switch to light theme" : "Switch to dark theme"}
            >
              {theme === "dark" ? <Sun aria-hidden="true" /> : <Moon aria-hidden="true" />}
            </button>
          ) : null}
        </div>
        <label className="xblox-palette-search">
          <span>Search blocks</span>
          <input
            value={paletteQuery}
            onChange={(event) => setPaletteQuery(event.target.value)}
            placeholder="Filter blocks or commands..."
            type="search"
          />
        </label>
        <div className="xblox-palette-scroll">
          {groupedNativePalette.map((group) => (
            <details key={`native:${group.label}`} className="xblox-palette-group xblox-native-palette-group" open>
              <summary>
                <span>{group.label}</span>
                <small>{group.items.length}</small>
              </summary>
              <div className="xblox-palette-group-list">
                {group.items.map((item) => (
                  <NativePaletteButton key={`${group.label}:${item.kind}`} item={item} />
                ))}
              </div>
            </details>
          ))}
          {groupedPalette.map((group) => (
            <details
              key={group.id}
              className="xblox-palette-group"
              open={openPaletteGroups.has(group.id)}
              onToggle={(event) => {
                const isOpen = event.currentTarget.open;
                setOpenPaletteGroups((current) => {
                  const next = new Set(current);
                  if (isOpen) next.add(group.id);
                  else next.delete(group.id);
                  return next;
                });
              }}
            >
              <summary>
                <span>{group.label}</span>
                <small>{group.kinds.length}</small>
              </summary>
              <div className="xblox-palette-group-list">
                {group.kinds.map((kind) => (
                  <PaletteButton key={kind} kind={kind} />
                ))}
              </div>
            </details>
          ))}
          {!groupedPalette.length ? <p className="xblox-palette-empty">No matching blocks.</p> : null}
        </div>
        {commandPalette.length ? (
          <details
            className="xblox-palette-group xblox-command-palette-group"
            open={openPaletteGroups.has("command-library")}
            onToggle={(event) => {
              const isOpen = event.currentTarget.open;
              setOpenPaletteGroups((current) => {
                const next = new Set(current);
                if (isOpen) next.add("command-library");
                else next.delete("command-library");
                return next;
              });
            }}
          >
            <summary>
              <span>Command Library</span>
              <small>{filteredCommandPalette.length}</small>
            </summary>
            <div className="xblox-command-palette-list">
              {filteredCommandPalette.map((command) => (
                <CommandPaletteButton key={command.id} command={command} />
              ))}
              {!filteredCommandPalette.length ? <p className="xblox-palette-empty">No matching commands.</p> : null}
            </div>
          </details>
        ) : null}
      </aside>

      <div style={styles.panel} className="xblox-tree-panel">
        {currentRootListPath ? <p className="xblox-folder-path">Current: {currentRootListPath}</p> : null}
        <div className="xblox-block-toolbar" aria-label="Selected block actions">
          {onSave ? (
            <button type="button" onClick={onSave} disabled={saveDisabled} title="Save XBlox document">
              <Save aria-hidden="true" />
              <span>Save</span>
            </button>
          ) : null}
          <button type="button" onClick={runSelected} disabled={!selection || !selectedBlock} title="Run selected block">
            <Play aria-hidden="true" />
            <span>Run</span>
          </button>
          <button type="button" onClick={runCurrentChain} disabled={!onRunChain || !currentLevelBlocks.length} title="Run current chain">
            <Play aria-hidden="true" />
            <span>Run chain</span>
          </button>
          <button type="button" onClick={onStopRun} disabled={!running || !onStopRun} title="Stop running sequence">
            <Square aria-hidden="true" />
            <span>Stop</span>
          </button>
          {clipboardActions.map((action) => {
            const Icon = action.icon;
            return (
              <button
                key={action.id}
                type="button"
                onClick={() => void executeAction(action.id)}
                disabled={action.disabled}
                title={action.shortcut ? `${action.label} (${action.shortcut})` : action.label}
              >
                {Icon ? <Icon aria-hidden="true" /> : null}
                <span>{action.label}</span>
              </button>
            );
          })}
          <button type="button" onClick={deleteSelected} disabled={!selectedPaths.size} title="Delete selected blocks">
            <Trash2 aria-hidden="true" />
            <span>Delete</span>
          </button>
          <button type="button" onClick={() => moveSelectedRows(-1)} disabled={!selectedPaths.size} title="Move selected blocks up">
            <ArrowUp aria-hidden="true" />
            <span>Move up</span>
          </button>
          <button type="button" onClick={() => moveSelectedRows(1)} disabled={!selectedPaths.size} title="Move selected blocks down">
            <ArrowDown aria-hidden="true" />
            <span>Move down</span>
          </button>
          <button type="button" onClick={enterSelectedBlock} disabled={!selectedBlock || !getChildren(selectedBlock).length} title="Open selected block folder">
            <FolderOpen aria-hidden="true" />
            <span>Open</span>
          </button>
          <button type="button" onClick={navigateToParentBlock} disabled={!folderStack.length} title="Back to parent block">
            <ArrowLeft aria-hidden="true" />
            <span>Back</span>
          </button>
        </div>
        <div
          ref={treeRef}
          role="tree"
          tabIndex={0}
          onKeyDown={(event) => {
            if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "c") {
              event.preventDefault();
              void executeAction(COPY_ACTION_ID);
            } else if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "v") {
              event.preventDefault();
              void executeAction(PASTE_ACTION_ID);
            } else if (event.key === "Delete") {
              event.preventDefault();
              deleteSelected();
            } else if (event.key === "F2") {
              event.preventDefault();
              focusInlineEditor();
            } else if (event.key === "Backspace") {
              event.preventDefault();
              navigateToParentBlock();
            } else if ((event.ctrlKey || event.metaKey) && event.key === "ArrowUp") {
              event.preventDefault();
              moveSelectedRows(-1);
            } else if ((event.ctrlKey || event.metaKey) && event.key === "ArrowDown") {
              event.preventDefault();
              moveSelectedRows(1);
            } else if (event.shiftKey && event.key === "ArrowDown") {
              event.preventDefault();
              extendKeyboardSelection(1);
            } else if (event.shiftKey && event.key === "ArrowUp") {
              event.preventDefault();
              extendKeyboardSelection(-1);
            } else if (event.key === "ArrowDown") {
              event.preventDefault();
              moveSelection(1);
            } else if (event.key === "ArrowUp") {
              event.preventDefault();
              moveSelection(-1);
            } else if (event.key === "ArrowRight" && selection) {
              event.preventDefault();
              moveRightThroughTree();
            } else if (event.key === "ArrowLeft" && selection) {
              event.preventDefault();
              moveLeftThroughTree();
            } else if ((event.ctrlKey || event.metaKey) && event.key === "Enter") {
              event.preventDefault();
              if (selectedBlock) setPropsDialogOpen(true);
            } else if (event.key === "Enter") {
              event.preventDefault();
              enterSelectedBlock();
            } else if (event.key.toLowerCase() === "r") {
              event.preventDefault();
              runSelected();
            }
          }}
          style={{ outline: "none" }}
          className="xblox-tree-scroll"
        >
          {rows.map((row) => (
            <TreeItem
              key={row.path}
              row={row}
              selected={selectedPaths.has(row.path)}
              expanded={open.has(row.path)}
              status={runState?.[row.path] ?? ("id" in row.block && typeof row.block.id === "string" ? runState?.[row.block.id] : undefined)}
              onSelect={(event) => selectRow(row.path, event)}
              onActivate={() => {
                setSelectedPaths(new Set([row.path]));
                setAnchorPath(row.path);
                publishSelection(row.path);
              }}
              onToggle={() => {
                setOpen((current) => {
                  const next = new Set(current);
                  if (next.has(row.path)) next.delete(row.path);
                  else next.add(row.path);
                  return next;
                });
              }}
              onDropLine={handleDropLine}
              onPatch={(patch) => onChange(updateAtPath(value, row.path, patch))}
              onContextMenu={(event) => {
                event.preventDefault();
                event.stopPropagation();
                if (!selectedPaths.has(row.path)) {
                  setSelectedPaths(new Set([row.path]));
                  setAnchorPath(row.path);
                  publishSelection(row.path);
                }
                setContextMenu({ x: event.clientX, y: event.clientY, path: row.path });
              }}
              onOpen={() => {
                setSelectedPaths(new Set([row.path]));
                setAnchorPath(row.path);
                publishSelection(row.path);
                const block = getBlockAtPath(value, row.path);
                const childGroups = block ? getChildren(block) : [];
                if (!block || !childGroups.length) return;
                setOpen((current) => new Set(current).add(row.path));
                const firstChildGroup = childGroups.find((group) => group.blocks.length > 0) ?? childGroups[0];
                const nextRootListPath = `${row.path}/${firstChildGroup.key}`;
                setFolderStack((current) => [...current, { listPath: nextRootListPath, entryPath: row.path }]);
                const childPath = firstChildGroup.blocks.length ? `${nextRootListPath}/0` : null;
                setSelectedPaths(childPath ? new Set([childPath]) : new Set());
                setAnchorPath(childPath);
                publishSelection(childPath);
              }}
            />
          ))}
          <RootDropZone onDropBlock={dropIntoRoot} />
        </div>
      </div>

      <aside style={styles.panel} className="xblox-property-panel">
        <section className="xblox-property-section">
          <h3>Props</h3>
          {propertyEditor}
        </section>
        <section className="xblox-scope-panel xblox-root-scope-panel">
          <div className="xblox-root-scope-head">
            <h3>Root Scope</h3>
            {onRootScopeChange ? (
              <button type="button" onClick={applyRootScopeDraft}>
                Apply
              </button>
            ) : null}
          </div>
          <textarea
            value={rootScopeDraft}
            readOnly={!onRootScopeChange}
            onChange={(event) => {
              setRootScopeDraft(event.target.value);
              setRootScopeError(null);
            }}
            onBlur={applyRootScopeDraft}
            rows={8}
            spellCheck={false}
            style={styles.input}
          />
          {rootScopeError ? <p className="xblox-root-scope-error">{rootScopeError}</p> : null}
        </section>
      </aside>
    </section>
    {contextMenu ? (
      <div
        className="xblox-context-menu"
        role="menu"
        style={{ left: contextMenu.x, top: contextMenu.y }}
        onClick={(event) => event.stopPropagation()}
        onContextMenu={(event) => event.preventDefault()}
      >
        {clipboardActions.map((action) => {
          const Icon = action.icon;
          return (
            <button
              key={action.id}
              type="button"
              role="menuitem"
              disabled={action.disabled}
              onClick={() => {
                setContextMenu(null);
                void executeAction(action.id, { path: contextMenu.path });
              }}
            >
              {Icon ? <Icon aria-hidden="true" /> : null}
              <span>{action.label}</span>
              {action.shortcut ? <small>{action.shortcut}</small> : null}
            </button>
          );
        })}
        <hr />
        <button
          type="button"
          role="menuitem"
          disabled={!onRunBlock}
          onClick={() => {
            setContextMenu(null);
            const block = getBlockAtPath(value, contextMenu.path);
            if (block) void onRunBlock?.(block, contextMenu.path);
          }}
        >
          <Play aria-hidden="true" />
          <span>Run</span>
          <small>r</small>
        </button>
        <button
          type="button"
          role="menuitem"
          onClick={() => {
            setContextMenu(null);
            setSelectedPaths(new Set([contextMenu.path]));
            setAnchorPath(contextMenu.path);
            publishSelection(contextMenu.path);
            setPropsDialogOpen(true);
          }}
        >
          <FolderOpen aria-hidden="true" />
          <span>Properties</span>
          <small>ctrl+enter</small>
        </button>
        <button
          type="button"
          role="menuitem"
          disabled={!selectedPaths.size}
          onClick={() => {
            setContextMenu(null);
            deleteSelected();
          }}
        >
          <Trash2 aria-hidden="true" />
          <span>Delete</span>
          <small>del</small>
        </button>
      </div>
    ) : null}
    {propsDialogOpen ? (
      <div className="xblox-props-dialog-backdrop" role="presentation" onMouseDown={() => setPropsDialogOpen(false)}>
        <div
          className="xblox-props-dialog"
          role="dialog"
          aria-modal="true"
          aria-label="Block properties"
          onMouseDown={(event) => event.stopPropagation()}
          onKeyDown={(event) => {
            if (event.key === "Escape") {
              event.preventDefault();
              setPropsDialogOpen(false);
            }
          }}
        >
          <div className="xblox-props-dialog-head">
            <h3>Block Properties</h3>
            <button type="button" onClick={() => setPropsDialogOpen(false)} aria-label="Close block properties">
              Close
            </button>
          </div>
          <div className="xblox-props-dialog-body">{propertyEditor}</div>
        </div>
      </div>
    ) : null}
    </>
  );
}
